@app.route('/api/cart/add', methods=['POST'])
@login_required
@validate_json({'product_id': int, 'quantity': int, 'price_type': str})
def add_to_cart():
    data = request.get_json()
    product_id = data['product_id']
    quantity = data['quantity']
    price_type = data['price_type']

    # Validate product exists and is available
    product = Product.query.get_or_404(product_id)
    if product.stock_quantity < quantity:
        return jsonify({'success': False, 'message': 'موجودی کافی نیست'}), 400

    # Calculate unit price
    if current_user.is_bulk_buyer:
        unit_price = getattr(product, f'bulk_price_{price_type}')
    else:
        unit_price = getattr(product, f'retail_price_{price_type}')

    # Check for existing cart item
    existing_item = Cart.query.filter_by(
        user_id=current_user.id,
        product_id=product_id,
        price_type=price_type
    ).first()

    if existing_item:
        existing_item.quantity += quantity
        existing_item.updated_at = datetime.utcnow()
    else:
        cart_item = Cart(
            user_id=current_user.id,
            product_id=product_id,
            quantity=quantity,
            price_type=price_type,
            unit_price=unit_price
        )
        db.session.add(cart_item)

    db.session.commit()

    # Send notification
    send_cart_notification(current_user.id, 'item_added', {
        'product_name': product.name,
        'quantity': quantity
    })

    return jsonify({
        'success': True,
        'message': 'محصول با موفقیت به سبد خرید اضافه شد',
        'cart_count': get_cart_count(current_user.id)
    })

