class CartComponent {
    constructor() {
        this.init();
        this.bindEvents();
    }

    init() {
        this.cartSidebar = $('#cart-sidebar');
        this.cartItems = $('#cart-items');
        this.cartTotal = $('#cart-total');
        this.cartCount = $('.cart-count');
    }

    bindEvents() {
        $(document).on('click', '.add-to-cart', this.handleAddToCart.bind(this));
        $(document).on('click', '.remove-from-cart', this.handleRemoveFromCart.bind(this));
        $(document).on('change', '.cart-quantity', this.handleQuantityChange.bind(this));
        $(document).on('click', '.save-for-later', this.handleSaveForLater.bind(this));
    }

    async handleAddToCart(e) {
        e.preventDefault();
        const button = $(e.currentTarget);
        const productId = button.data('product-id');
        const quantity = parseInt($(`#quantity_${productId}`).val()) || 1;
        const priceType = $(`input[name="price_type_${productId}"]:checked`).val() || 'cash';

        // Show loading state
        this.showLoading(button);

        try {
            const response = await this.addToCart(productId, quantity, priceType);
            if (response.success) {
                this.showSuccessAnimation(button);
                this.updateCartDisplay();
                this.showNotification(response.message, 'success');
            } else {
                this.showNotification(response.message, 'error');
            }
        } catch (error) {
            this.showNotification('خطا در ارتباط با سرور', 'error');
        } finally {
            this.hideLoading(button);
        }
    }

    async addToCart(productId, quantity, priceType) {
        const response = await fetch('/api/cart/add', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': this.getCSRFToken()
            },
            body: JSON.stringify({
                product_id: productId,
                quantity: quantity,
                price_type: priceType
            })
        });

        return await response.json();
    }

    showSuccessAnimation(button) {
        button.addClass('btn-success').html('<i class="fas fa-check"></i> اضافه شد');
        setTimeout(() => {
            button.removeClass('btn-success').html('<i class="fas fa-cart-plus"></i> اضافه به سبد');
        }, 2000);
    }

    updateCartDisplay() {
        this.updateCartCount();
        this.updateCartTotals();
        this.updateCartItems();
    }

    async updateCartCount() {
        try {
            const response = await fetch('/api/cart/count');
            const data = await response.json();
            this.cartCount.text(data.count).toggle(data.count > 0);
        } catch (error) {
            console.error('Error updating cart count:', error);
        }
    }

    showNotification(message, type) {
        const alertClass = type === 'success' ? 'alert-success' : 'alert-danger';
        const notification = $(`
            <div class="alert ${alertClass} alert-dismissible fade show position-fixed" 
                 style="top: 20px; right: 20px; z-index: 9999; min-width: 300px;">
                ${message}
                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
            </div>
        `);

        $('body').append(notification);

        setTimeout(() => {
            notification.alert('close');
        }, 5000);
    }
}
